--
-- 테이블 구조 `panel_measurements`
--

CREATE TABLE `panel_measurements` (
  `id` int(11) NOT NULL COMMENT '측정 ID',
  `ipark_check` tinyint(1) DEFAULT 0 COMMENT '아이파크 신규 체크 여부 (0: 해제, 1: 체크)',
  `production_height1_11` int(11) DEFAULT NULL COMMENT '1,11번 패널 제작 높이 (mm)',
  `transom_excluded` tinyint(1) DEFAULT 0 COMMENT '트랜섬 제외 여부 (0=포함, 1=제외)',
  `molding_included` tinyint(1) DEFAULT 0 COMMENT '몰딩 포함 여부 (0: 미포함, 1: 포함)',
  `site_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '현장명',
  `site_address` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '현장 주소',
  `client_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '고객명/업체명',
  `client_phone` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '고객 연락처',
  `project_manager` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '프로젝트 담당자',
  `elevator_count` tinyint(4) DEFAULT 1 COMMENT '엘리베이터 대수',
  `created_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '등록자 ID',
  `measurer_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '측정자명',
  `measurer_id` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '측정자 ID',
  `measurement_date` date NOT NULL COMMENT '측정일자',
  `car_inside_width` int(11) NOT NULL COMMENT '카 내부 가로 (mm)',
  `car_inside_depth` int(11) NOT NULL COMMENT '카 내부 깊이 (mm)',
  `car_inside_height` int(11) NOT NULL COMMENT '카 내부 높이 (mm)',
  `material_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '의장재질 타입',
  `material_thickness` decimal(3,1) DEFAULT NULL COMMENT '의장재질 두께 (mm)',
  `panel_data` text COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '패널 1~11번 정보 (JSON 형태)',
  `transom_data` text COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Transom 12번 정보 (JSON 형태)',
  `notes` text COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '특이사항',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp() COMMENT '생성일시',
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp() COMMENT '최종 수정일시',
  `project_type` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT '신규' COMMENT '프로젝트 구분 (신규/MOD)',
  `panel_corners_excluded` tinyint(1) DEFAULT 1 COMMENT '1,11번 패널 제외 여부 (0=포함, 1=제외)',
  `production_height` int(11) DEFAULT NULL COMMENT '제작 높이 (mm)',
  `updated_production_settings_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp() COMMENT '제작설정 마지막 수정일시',
  `make_panel_data` text COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '제작 사이즈가 적용된 패널 데이터 (JSON 문자열)',
  `molding_data` text COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '몰딩 데이터 (JSON 형태)'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='패널 측정 정보';

